void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float shift = U.p0.x * sin(uv.y * 35.0 + iTime * 1.5);
    vec3 src = texture(iChannel0, clamp(uv + vec2(shift, 0.0), 0.0, 1.0)).rgb;
    float l = dot(src, vec3(0.2126, 0.7152, 0.0722));
    // Push the midtones down so the subject reads against the room instead
    // of the whole frame flooding to one cyan.
    l = pow(clamp(l, 0.0, 1.0), 1.9);
    float scan = 0.55 + 0.45 * sin(fragCoord.y * 2.2 - iTime * 6.0);
    float roll = 0.85 + 0.15 * sin(uv.y * 3.0 - iTime * 0.7);
    vec3 c = vec3(0.10, 0.95, 1.0) * l * scan * roll * 2.1;
    // A cold rim where the picture changes fastest reads as an edge glow.
    c += vec3(0.4, 1.0, 1.0) * pow(l, 6.0) * 0.5;
    fragColor = vec4(mix(src, c, clamp(U.p0.y, 0.0, 1.0)), 1.0);
}
